import type { MonsterAction, MonsterActionKind, MonsterDefinition } from "../shared/types";

type Props = {
  monster: MonsterDefinition;
  onChange: (monster: MonsterDefinition) => void;
  onSave: () => void;
  onCancel: () => void;
};

const actionKinds: MonsterActionKind[] = ["melee", "ranged", "other"];

export function MonsterDraftEditor({ monster, onChange, onSave, onCancel }: Props) {
  function update(patch: Partial<MonsterDefinition>) {
    onChange({ ...monster, ...patch });
  }

  function updateAbility(key: keyof MonsterDefinition["abilities"], value: number) {
    update({
      abilities: {
        ...monster.abilities,
        [key]: value,
      },
    });
  }

  function updateAction(index: number, patch: Partial<MonsterAction>) {
    update({
      actions: monster.actions.map((action, actionIndex) =>
        actionIndex === index ? { ...action, ...patch } : action,
      ),
    });
  }

  function removeAction(index: number) {
    update({
      actions: monster.actions.filter((_, actionIndex) => actionIndex !== index),
    });
  }

  function addAction() {
    update({
      actions: [
        ...monster.actions,
        {
          id: `action-${monster.actions.length + 1}`,
          name: "New Action",
          kind: "melee",
          description: "Melee weapon attack.",
          attackBonus: 0,
          damageDice: "1d6",
          damageType: "bludgeoning",
          reachFeet: 5,
        },
      ],
    });
  }

  return (
    <div className="draft-editor">
      <div className="editor-grid two">
        <label>
          Name
          <input value={monster.name} onChange={(event) => update({ name: event.target.value })} />
        </label>
        <label>
          Type
          <input value={monster.type} onChange={(event) => update({ type: event.target.value })} />
        </label>
        <label>
          Size
          <input value={monster.size} onChange={(event) => update({ size: event.target.value })} />
        </label>
        <label>
          CR
          <input
            type="number"
            step="0.125"
            min={0}
            max={30}
            value={monster.challengeRating}
            onChange={(event) => update({ challengeRating: Number(event.target.value) })}
          />
        </label>
        <label>
          AC
          <input
            type="number"
            min={1}
            max={40}
            value={monster.armorClass}
            onChange={(event) => update({ armorClass: Number(event.target.value) })}
          />
        </label>
        <label>
          HP
          <input
            type="number"
            min={1}
            max={1000}
            value={monster.hitPoints}
            onChange={(event) => update({ hitPoints: Number(event.target.value) })}
          />
        </label>
        <label>
          Speed ft.
          <input
            type="number"
            min={0}
            max={240}
            value={monster.speedFeet}
            onChange={(event) => update({ speedFeet: Number(event.target.value) })}
          />
        </label>
        <label>
          Image URL
          <input value={monster.imageUrl ?? ""} onChange={(event) => update({ imageUrl: event.target.value || undefined })} />
        </label>
      </div>

      <div className="editor-grid six">
        {(["str", "dex", "con", "int", "wis", "cha"] as const).map((ability) => (
          <label key={ability}>
            {ability.toUpperCase()}
            <input
              type="number"
              value={monster.abilities[ability]}
              onChange={(event) => updateAbility(ability, Number(event.target.value))}
            />
          </label>
        ))}
      </div>

      <ArrayTextField
        label="Traits"
        values={monster.traits}
        onChange={(traits) => update({ traits })}
      />
      <ArrayTextField
        label="Damage vulnerabilities"
        values={monster.damageVulnerabilities}
        onChange={(damageVulnerabilities) => update({ damageVulnerabilities })}
      />
      <ArrayTextField
        label="Damage resistances"
        values={monster.damageResistances}
        onChange={(damageResistances) => update({ damageResistances })}
      />
      <ArrayTextField
        label="Damage immunities"
        values={monster.damageImmunities}
        onChange={(damageImmunities) => update({ damageImmunities })}
      />
      <ArrayTextField
        label="Condition immunities"
        values={monster.conditionImmunities}
        onChange={(conditionImmunities) => update({ conditionImmunities })}
      />

      <div className="result-block">
        <div className="section-heading">
          <h2>Actions</h2>
          <button onClick={addAction} type="button">Add Action</button>
        </div>
        {monster.actions.map((action, index) => (
          <div className="action-editor" key={`${action.id}-${index}`}>
            <div className="editor-grid two">
              <label>
                Action name
                <input value={action.name} onChange={(event) => updateAction(index, { name: event.target.value })} />
              </label>
              <label>
                Kind
                <select
                  value={action.kind}
                  onChange={(event) => updateAction(index, { kind: event.target.value as MonsterActionKind })}
                >
                  {actionKinds.map((kind) => (
                    <option value={kind} key={kind}>{kind}</option>
                  ))}
                </select>
              </label>
              <label>
                Attack bonus
                <input
                  type="number"
                  value={action.attackBonus ?? ""}
                  onChange={(event) => updateAction(index, { attackBonus: optionalNumber(event.target.value) })}
                />
              </label>
              <label>
                Damage dice
                <input value={action.damageDice ?? ""} onChange={(event) => updateAction(index, { damageDice: event.target.value || undefined })} />
              </label>
              <label>
                Damage type
                <input value={action.damageType ?? ""} onChange={(event) => updateAction(index, { damageType: event.target.value || undefined })} />
              </label>
              <label>
                Reach ft.
                <input
                  type="number"
                  value={action.reachFeet ?? ""}
                  onChange={(event) => updateAction(index, { reachFeet: optionalNumber(event.target.value) })}
                />
              </label>
              <label>
                Range ft.
                <input
                  type="number"
                  value={action.rangeFeet ?? ""}
                  onChange={(event) => updateAction(index, { rangeFeet: optionalNumber(event.target.value) })}
                />
              </label>
              <label>
                Long range ft.
                <input
                  type="number"
                  value={action.longRangeFeet ?? ""}
                  onChange={(event) => updateAction(index, { longRangeFeet: optionalNumber(event.target.value) })}
                />
              </label>
            </div>
            <label>
              Description
              <textarea
                value={action.description}
                rows={2}
                onChange={(event) => updateAction(index, { description: event.target.value })}
              />
            </label>
            <button type="button" onClick={() => removeAction(index)} disabled={monster.actions.length <= 1}>
              Remove Action
            </button>
          </div>
        ))}
      </div>

      <div className="toolbar">
        <button className="primary" onClick={onSave} type="button">Save Monster</button>
        <button onClick={onCancel} type="button">Cancel</button>
      </div>
    </div>
  );
}

function ArrayTextField({
  label,
  values,
  onChange,
}: {
  label: string;
  values: string[];
  onChange: (values: string[]) => void;
}) {
  return (
    <label>
      {label}
      <textarea
        value={values.join("\n")}
        rows={2}
        onChange={(event) => onChange(linesToArray(event.target.value))}
      />
    </label>
  );
}

function linesToArray(value: string): string[] {
  return value
    .split(/\r?\n|,/)
    .map((line) => line.trim())
    .filter(Boolean);
}

function optionalNumber(value: string): number | undefined {
  if (value.trim() === "") {
    return undefined;
  }
  const number = Number(value);
  return Number.isFinite(number) ? number : undefined;
}

