import {
  Activity,
  Bot,
  Check,
  Crosshair,
  Edit3,
  FileText,
  Image as ImageIcon,
  Pause,
  Play,
  Plus,
  RotateCcw,
  Save,
  Search,
  Settings,
  Shield,
  Upload,
  Wand2,
} from "lucide-react";
import { useCallback, useEffect, useMemo, useState, type ClipboardEvent } from "react";
import { createCompanionApi, DEFAULT_COMPANION_URL, saveTokenArt, type CompanionHealth } from "./client/api";
import { MonsterDraftEditor } from "./components/MonsterDraftEditor";
import {
  applyTurnResolution,
  markSelectedAsPlayers,
  pickTokenArtFromAtlas,
  readSceneSnapshot,
  spawnEncounterPlan,
  uploadTokenFiles,
} from "./extension/owlbear";
import type {
  CombatantState,
  CompanionSettings,
  EncounterPlan,
  MonsterDefinition,
  SceneSnapshot,
  TurnProposal,
  TurnResolution,
} from "./shared/types";

type Tab = "encounter" | "turns" | "library" | "settings";
type LibraryMode = "browse" | "text" | "image" | "create";

const CLIENT_DEFAULT_SETTINGS: CompanionSettings = {
  lmStudioBaseUrl: "http://localhost:1234/v1",
  lmStudioModel: "",
  campaignRuleset: "2014-5e",
  companionPort: 8765,
  defaultMonsterCount: 4,
  tokenArt: {},
};

export function App() {
  const [tab, setTab] = useState<Tab>("encounter");
  const [companionUrl, setCompanionUrl] = useState(localStorage.getItem("companionUrl") ?? DEFAULT_COMPANION_URL);
  const api = useMemo(() => createCompanionApi(companionUrl), [companionUrl]);
  const [health, setHealth] = useState<CompanionHealth | undefined>();
  const [settings, setSettings] = useState<CompanionSettings | undefined>();
  const [scene, setScene] = useState<SceneSnapshot | undefined>();
  const [monsters, setMonsters] = useState<MonsterDefinition[]>([]);
  const [combatants, setCombatants] = useState<CombatantState[]>([]);
  const [prompt, setPrompt] = useState("Skeletons rose up around the party.");
  const [plan, setPlan] = useState<EncounterPlan | undefined>();
  const [proposal, setProposal] = useState<TurnProposal | undefined>();
  const [lastResolution, setLastResolution] = useState<TurnResolution | undefined>();
  const [busy, setBusy] = useState<string | undefined>();
  const [notice, setNotice] = useState<string | undefined>();
  const [error, setError] = useState<string | undefined>();
  const [monsterSearch, setMonsterSearch] = useState("");
  const [importText, setImportText] = useState("");
  const [libraryMode, setLibraryMode] = useState<LibraryMode>("browse");
  const [draftMonster, setDraftMonster] = useState<MonsterDefinition | undefined>();
  const [imageDataUrl, setImageDataUrl] = useState("");
  const [imageNotes, setImageNotes] = useState("");
  const [createDescription, setCreateDescription] = useState("");
  const [createTargetCr, setCreateTargetCr] = useState("");
  const [createRole, setCreateRole] = useState("");
  const [selectedMonsterId, setSelectedMonsterId] = useState("srd-2014:skeleton");
  const [modelOptions, setModelOptions] = useState<{ id: string }[]>([]);

  const refresh = useCallback(async () => {
    setError(undefined);
    const sceneResult = await readSceneSnapshot();
    setScene(sceneResult);

    try {
      const [healthResult, settingsResult, monstersResult] = await Promise.all([
        api.health(),
        api.settings(),
        api.monsters(monsterSearch),
      ]);
      setHealth(healthResult);
      setSettings(settingsResult);
      setMonsters(monstersResult.monsters);
      const sync = await api.syncCombat(sceneResult);
      setCombatants(sync.combatants);
    } catch (caught) {
      setHealth(undefined);
      setError(caught instanceof Error ? caught.message : String(caught));
    }
  }, [api, monsterSearch]);

  useEffect(() => {
    refresh().catch((caught: Error) => setError(caught.message));
  }, [refresh]);

  async function run<T>(label: string, action: () => Promise<T>): Promise<T | undefined> {
    setBusy(label);
    setError(undefined);
    setNotice(undefined);
    try {
      const result = await action();
      return result;
    } catch (caught) {
      setError(caught instanceof Error ? caught.message : String(caught));
      return undefined;
    } finally {
      setBusy(undefined);
    }
  }

  async function syncScene() {
    await run("Syncing", async () => {
      const snapshot = await readSceneSnapshot();
      setScene(snapshot);
      const synced = await api.syncCombat(snapshot);
      setCombatants(synced.combatants);
      setNotice(`Synced ${snapshot.playerTokens.length} player token(s), ${snapshot.monsterTokens.length} monster token(s).`);
    });
  }

  async function tagPlayers() {
    await run("Tagging", async () => {
      const count = await markSelectedAsPlayers();
      await syncScene();
      setNotice(count > 0 ? `Tagged ${count} selected token(s) as players.` : "No selected Owlbear tokens to tag.");
    });
  }

  async function createPlan() {
    await run("Planning", async () => {
      const snapshot = await readSceneSnapshot();
      setScene(snapshot);
      const result = await api.planEncounter(prompt, snapshot);
      setPlan(result.plan);
      setProposal(undefined);
      setLastResolution(undefined);
    });
  }

  async function spawnPlan() {
    if (!plan || !settings) {
      return;
    }
    await run("Spawning", async () => {
      await spawnEncounterPlan({ plan, tokenArt: settings.tokenArt });
      const snapshot = await readSceneSnapshot();
      setScene(snapshot);
      const synced = await api.syncCombat(snapshot);
      setCombatants(synced.combatants);
      setNotice(`Spawned ${plan.monsters.reduce((sum, monster) => sum + monster.count, 0)} monster token(s).`);
    });
  }

  async function proposeTurn() {
    await run("Thinking", async () => {
      const snapshot = await readSceneSnapshot();
      setScene(snapshot);
      const result = await api.proposeTurn(snapshot);
      setProposal(result.proposal);
      setCombatants(result.combatants);
      setTab("turns");
    });
  }

  async function applyProposal() {
    if (!proposal) {
      return;
    }
    await run("Applying", async () => {
      const snapshot = await readSceneSnapshot();
      const result = await api.resolveTurn(snapshot, proposal);
      await applyTurnResolution(result.resolution);
      const nextScene = await readSceneSnapshot();
      setScene(nextScene);
      setCombatants(result.combatants);
      setLastResolution(result.resolution);
      setProposal(undefined);
    });
  }

  async function undoLastMove() {
    if (!lastResolution || lastResolution.movementApplied.length < 2) {
      return;
    }
    await run("Undoing", async () => {
      const reverseMove: TurnResolution = {
        ...lastResolution,
        movementApplied: [
          lastResolution.movementApplied[lastResolution.movementApplied.length - 1],
          lastResolution.movementApplied[0],
        ],
        attacks: [],
        monsterUpdates: [],
        log: ["Last monster movement undone locally."],
      };
      await applyTurnResolution(reverseMove);
      const snapshot = await readSceneSnapshot();
      setScene(snapshot);
      const synced = await api.syncCombat(snapshot);
      setCombatants(synced.combatants);
      setNotice("Last monster movement undone.");
    });
  }

  async function importMonster() {
    await run("Importing", async () => {
      const parsed = JSON.parse(importText);
      const result = await api.importMonster(parsed);
      setImportText("");
      setSelectedMonsterId(result.monster.id);
      const refreshed = await api.monsters(monsterSearch);
      setMonsters(refreshed.monsters);
      setNotice(`Imported ${result.monster.name}.`);
    });
  }

  async function draftFromText() {
    await run("Parsing Text", async () => {
      const result = await api.draftMonsterFromText(importText);
      setDraftMonster(result.monster);
      setSelectedMonsterId(result.monster.id);
      setNotice(`Drafted ${result.monster.name}. Review it before saving.`);
    });
  }

  async function draftFromImage() {
    if (!imageDataUrl) {
      setError("Choose or paste a stat block image first.");
      return;
    }
    await run("Parsing Image", async () => {
      const result = await api.draftMonsterFromImage(imageDataUrl, imageNotes);
      setDraftMonster(result.monster);
      setSelectedMonsterId(result.monster.id);
      setNotice(`Drafted ${result.monster.name}. Review it before saving.`);
    });
  }

  async function generateDraftMonster() {
    await run("Generating", async () => {
      const result = await api.generateMonster({
        description: createDescription,
        targetChallengeRating: createTargetCr.trim() ? Number(createTargetCr) : undefined,
        role: createRole.trim() || undefined,
      });
      setDraftMonster(result.monster);
      setSelectedMonsterId(result.monster.id);
      setNotice(`Generated ${result.monster.name}. Review it before saving.`);
    });
  }

  async function saveDraftMonster() {
    if (!draftMonster) {
      return;
    }
    await run("Saving Monster", async () => {
      const result = await api.updateMonster(draftMonster.id, draftMonster);
      setDraftMonster(undefined);
      setSelectedMonsterId(result.monster.id);
      const refreshed = await api.monsters(monsterSearch);
      setMonsters(refreshed.monsters);
      setNotice(`Saved ${result.monster.name} to the local library.`);
    });
  }

  function editSelectedMonster() {
    if (!selectedMonster) {
      return;
    }
    setDraftMonster(JSON.parse(JSON.stringify(selectedMonster)) as MonsterDefinition);
    setNotice(`Editing ${selectedMonster.name}. Save creates or updates a local library entry.`);
  }

  async function chooseStatBlockImage(files: FileList | null) {
    const file = files?.[0];
    if (!file) {
      return;
    }
    const dataUrl = await fileToDataUrl(file);
    setImageDataUrl(dataUrl);
    setNotice(`Loaded ${file.name}.`);
  }

  async function handleImagePaste(event: ClipboardEvent<HTMLDivElement>) {
    const image = Array.from(event.clipboardData.files).find((file) => file.type.startsWith("image/"));
    if (!image) {
      return;
    }
    event.preventDefault();
    const dataUrl = await fileToDataUrl(image);
    setImageDataUrl(dataUrl);
    setNotice("Pasted stat block image.");
  }

  async function assignAtlasArt() {
    if (!settings) {
      return;
    }
    await run("Picking Art", async () => {
      const art = await pickTokenArtFromAtlas(selectedMonsterId);
      if (!art) {
        setNotice("No Atlas image selected.");
        return;
      }
      const updated = await saveTokenArt(api, settings, art);
      setSettings(updated);
      setNotice("Token art assigned.");
    });
  }

  async function uploadFiles(files: FileList | null) {
    if (!files) {
      return;
    }
    await run("Uploading", async () => {
      const count = await uploadTokenFiles(files);
      setNotice(count > 0 ? `Uploaded ${count} file(s) to Owlbear Atlas.` : "Open inside Owlbear to upload token art.");
    });
  }

  async function saveSettings() {
    await run("Saving", async () => {
      localStorage.setItem("companionUrl", companionUrl);
      if (!settings) {
        return;
      }
      const updated = await api.updateSettings(settings);
      setSettings(updated);
      setNotice("Settings saved.");
      const models = await api.models().catch(() => ({ models: [] }));
      setModelOptions(models.models);
    });
  }

  const selectedMonster = monsters.find((monster) => monster.id === selectedMonsterId) ?? monsters[0];
  const displaySettings = settings ?? CLIENT_DEFAULT_SETTINGS;

  return (
    <main className="app-shell">
      <header className="topbar">
        <div>
          <h1>Combat Director</h1>
          <p className={health?.ok ? "status ok" : "status"}>{health?.ok ? "Companion online" : "Companion offline"}</p>
        </div>
        <button className="icon-button" onClick={() => void refresh()} title="Refresh">
          <Activity size={18} />
        </button>
      </header>

      <nav className="tabs" aria-label="Views">
        <button className={tab === "encounter" ? "active" : ""} onClick={() => setTab("encounter")}>
          <Crosshair size={16} /> Encounter
        </button>
        <button className={tab === "turns" ? "active" : ""} onClick={() => setTab("turns")}>
          <Bot size={16} /> Turns
        </button>
        <button className={tab === "library" ? "active" : ""} onClick={() => setTab("library")}>
          <Shield size={16} /> Library
        </button>
        <button className={tab === "settings" ? "active" : ""} onClick={() => setTab("settings")}>
          <Settings size={16} /> Settings
        </button>
      </nav>

      {notice && <div className="notice">{notice}</div>}
      {error && <div className="error">{error}</div>}
      {busy && <div className="busy">{busy}...</div>}

      {tab === "encounter" && (
        <section className="panel">
          <div className="scene-strip">
            <span>{scene?.playerTokens.length ?? 0} PCs</span>
            <span>{scene?.monsterTokens.length ?? 0} monsters</span>
            <span>{combatants.length} tracked</span>
          </div>
          <div className="toolbar">
            <button onClick={() => void tagPlayers()}>
              <Shield size={16} /> Tag PCs
            </button>
            <button onClick={() => void syncScene()}>
              <Activity size={16} /> Sync
            </button>
          </div>
          <label>
            Encounter prompt
            <textarea value={prompt} onChange={(event) => setPrompt(event.target.value)} rows={4} />
          </label>
          <div className="toolbar">
            <button className="primary" onClick={() => void createPlan()}>
              <Bot size={16} /> Plan
            </button>
            <button disabled={!plan} onClick={() => void spawnPlan()}>
              <Plus size={16} /> Spawn
            </button>
            <button disabled={combatants.length === 0} onClick={() => void proposeTurn()}>
              <Play size={16} /> Turn
            </button>
          </div>
          {plan && (
            <div className="result-block">
              <h2>{plan.source === "llm" ? "LLM Plan" : "Fallback Plan"}</h2>
              {plan.monsters.map((monster) => (
                <div className="row" key={monster.planId}>
                  <strong>{monster.count}x {monster.name}</strong>
                  <span>{monster.reason}</span>
                </div>
              ))}
              {plan.notes.map((note) => (
                <p key={note}>{note}</p>
              ))}
            </div>
          )}
        </section>
      )}

      {tab === "turns" && (
        <section className="panel">
          <div className="toolbar">
            <button onClick={() => void proposeTurn()}>
              <Bot size={16} /> Propose
            </button>
            <button disabled={!proposal?.validation.ok} className="primary" onClick={() => void applyProposal()}>
              <Check size={16} /> Apply
            </button>
            <button disabled={!proposal} onClick={() => setProposal(undefined)}>
              <Pause size={16} /> Pause
            </button>
            <button disabled={!lastResolution} onClick={() => void undoLastMove()} title="Undo last monster movement">
              <RotateCcw size={16} />
            </button>
          </div>
          {proposal ? (
            <div className="result-block">
              <h2>{proposal.actionName}</h2>
              <p>{proposal.explanation}</p>
              <div className={proposal.validation.ok ? "validation ok" : "validation"}>
                {proposal.validation.ok ? "Legal turn" : proposal.validation.errors.join(" ")}
              </div>
              <dl>
                <dt>Targets</dt>
                <dd>{proposal.targetTokenIds.length ? proposal.targetTokenIds.join(", ") : "None"}</dd>
                <dt>Move points</dt>
                <dd>{proposal.movementPath.length}</dd>
              </dl>
            </div>
          ) : (
            <div className="empty-state">No turn proposal pending.</div>
          )}
          {lastResolution && (
            <div className="result-block">
              <h2>Last Result</h2>
              {lastResolution.log.map((line) => (
                <p key={line}>{line}</p>
              ))}
              {lastResolution.attacks.map((attack) => (
                <div className="row" key={`${attack.targetTokenId}-${attack.actionName}`}>
                  <strong>{attack.actionName}</strong>
                  <span>
                    Attack {attack.attackTotal ?? "n/a"}, damage {attack.damage ?? "n/a"} {attack.damageType ?? ""}
                  </span>
                </div>
              ))}
            </div>
          )}
        </section>
      )}

      {tab === "library" && (
        <section className="panel">
          <div className="tabs sub-tabs" aria-label="Library modes">
            <button className={libraryMode === "browse" ? "active" : ""} onClick={() => setLibraryMode("browse")}>
              <Search size={16} /> Browse
            </button>
            <button className={libraryMode === "text" ? "active" : ""} onClick={() => setLibraryMode("text")}>
              <FileText size={16} /> Text
            </button>
            <button className={libraryMode === "image" ? "active" : ""} onClick={() => setLibraryMode("image")}>
              <ImageIcon size={16} /> Image
            </button>
            <button className={libraryMode === "create" ? "active" : ""} onClick={() => setLibraryMode("create")}>
              <Wand2 size={16} /> Create
            </button>
          </div>

          <label className="search-box">
            <Search size={16} />
            <input
              value={monsterSearch}
              onChange={(event) => setMonsterSearch(event.target.value)}
              onBlur={() => void refresh()}
              placeholder="Search monsters"
            />
          </label>
          <select value={selectedMonster?.id ?? ""} onChange={(event) => setSelectedMonsterId(event.target.value)}>
            {monsters.map((monster) => (
              <option value={monster.id} key={monster.id}>
                {monster.name} CR {monster.challengeRating}
              </option>
            ))}
          </select>
          {selectedMonster && (
            <div className="statline">
              <span>AC {selectedMonster.armorClass}</span>
              <span>HP {selectedMonster.hitPoints}</span>
              <span>{selectedMonster.speedFeet} ft</span>
            </div>
          )}

          {libraryMode === "browse" && (
            <>
              <div className="toolbar">
                <button onClick={editSelectedMonster} disabled={!selectedMonster}>
                  <Edit3 size={16} /> Edit
                </button>
                <button onClick={() => void assignAtlasArt()}>
                  <Shield size={16} /> Atlas Art
                </button>
                <label className="file-button">
                  <Upload size={16} /> Upload
                  <input type="file" accept="image/*" multiple onChange={(event) => void uploadFiles(event.target.files)} />
                </label>
              </div>
              {selectedMonster && (
                <div className="result-block">
                  <h2>{selectedMonster.name}</h2>
                  <p>{selectedMonster.size} {selectedMonster.type}, CR {selectedMonster.challengeRating}</p>
                  {selectedMonster.traits.map((trait) => (
                    <p key={trait}>{trait}</p>
                  ))}
                  {selectedMonster.actions.map((action) => (
                    <div className="row" key={action.id}>
                      <strong>{action.name}</strong>
                      <span>
                        {action.attackBonus !== undefined ? `+${action.attackBonus} to hit` : "No roll"} {action.damageDice ?? ""}
                        {action.damageType ? ` ${action.damageType}` : ""}
                      </span>
                    </div>
                  ))}
                </div>
              )}
            </>
          )}

          {libraryMode === "text" && (
            <>
              <label>
                Pasted stat block text
                <textarea value={importText} onChange={(event) => setImportText(event.target.value)} rows={9} />
              </label>
              <div className="toolbar">
                <button className="primary" disabled={importText.trim().length < 10} onClick={() => void draftFromText()}>
                  <Bot size={16} /> Parse Text
                </button>
                <button disabled={!importText.trim()} onClick={() => void importMonster()}>
                  <Plus size={16} /> Import JSON
                </button>
              </div>
            </>
          )}

          {libraryMode === "image" && (
            <>
              <div className="paste-zone" tabIndex={0} onPaste={(event) => void handleImagePaste(event)}>
                {imageDataUrl ? <img src={imageDataUrl} alt="Stat block preview" /> : <span>Paste stat block image here</span>}
              </div>
              <div className="toolbar">
                <label className="file-button">
                  <Upload size={16} /> Choose Image
                  <input type="file" accept="image/*" onChange={(event) => void chooseStatBlockImage(event.target.files)} />
                </label>
                <button className="primary" disabled={!imageDataUrl} onClick={() => void draftFromImage()}>
                  <Bot size={16} /> Parse Image
                </button>
              </div>
              <label>
                Image notes
                <textarea value={imageNotes} onChange={(event) => setImageNotes(event.target.value)} rows={3} />
              </label>
            </>
          )}

          {libraryMode === "create" && (
            <>
              <label>
                Enemy description
                <textarea
                  value={createDescription}
                  onChange={(event) => setCreateDescription(event.target.value)}
                  rows={6}
                />
              </label>
              <div className="editor-grid two">
                <label>
                  Target CR
                  <input
                    type="number"
                    step="0.125"
                    min={0}
                    max={30}
                    value={createTargetCr}
                    onChange={(event) => setCreateTargetCr(event.target.value)}
                  />
                </label>
                <label>
                  Combat role
                  <input value={createRole} onChange={(event) => setCreateRole(event.target.value)} />
                </label>
              </div>
              <button className="primary" disabled={createDescription.trim().length < 10} onClick={() => void generateDraftMonster()}>
                <Wand2 size={16} /> Generate
              </button>
            </>
          )}

          {draftMonster && (
            <MonsterDraftEditor
              monster={draftMonster}
              onChange={setDraftMonster}
              onSave={() => void saveDraftMonster()}
              onCancel={() => setDraftMonster(undefined)}
            />
          )}
        </section>
      )}

      {tab === "settings" && (
        <section className="panel">
          <label>
            Companion URL
            <input value={companionUrl} onChange={(event) => setCompanionUrl(event.target.value)} />
          </label>
          <label>
            LM Studio base URL
            <input
              value={displaySettings.lmStudioBaseUrl}
              onChange={(event) => setSettings({ ...displaySettings, lmStudioBaseUrl: event.target.value })}
            />
          </label>
          <label>
            Model
            <input
              list="models"
              value={displaySettings.lmStudioModel}
              onChange={(event) => setSettings({ ...displaySettings, lmStudioModel: event.target.value })}
            />
            <datalist id="models">
              {modelOptions.map((model) => (
                <option value={model.id} key={model.id} />
              ))}
            </datalist>
          </label>
          <label>
            Default monster count
            <input
              type="number"
              min={1}
              max={20}
              value={displaySettings.defaultMonsterCount}
              onChange={(event) =>
                setSettings({ ...displaySettings, defaultMonsterCount: Number(event.target.value) })
              }
            />
          </label>
          <button className="primary" onClick={() => void saveSettings()}>
            <Save size={16} /> Save
          </button>
        </section>
      )}
    </main>
  );
}

function fileToDataUrl(file: File): Promise<string> {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(String(reader.result));
    reader.onerror = () => reject(reader.error ?? new Error("Could not read file."));
    reader.readAsDataURL(file);
  });
}
