import OBR, { buildImage, buildImageUpload, isImage } from "@owlbear-rodeo/sdk";
import type { EncounterPlan, SceneSnapshot, TokenArtMapping, TurnResolution, Vector2 } from "../shared/types";

export const METADATA_KEY = "local.combat-director/metadata";

type CombatMetadata = {
  role?: "pc" | "monster";
  monsterDefinitionId?: string;
  combatantId?: string;
  defeated?: boolean;
};

export async function isOwlbearReady(): Promise<boolean> {
  if (!OBR.isAvailable) {
    return false;
  }
  if (!OBR.isReady) {
    await new Promise<void>((resolve) => OBR.onReady(resolve));
  }
  return OBR.scene.isReady();
}

export async function readSceneSnapshot(): Promise<SceneSnapshot> {
  const ready = await isOwlbearReady();
  if (!ready) {
    return demoSceneSnapshot();
  }

  const [items, dpi, scale, type, measurement] = await Promise.all([
    OBR.scene.items.getItems(),
    OBR.scene.grid.getDpi(),
    OBR.scene.grid.getScale(),
    OBR.scene.grid.getType(),
    OBR.scene.grid.getMeasurement(),
  ]);

  const imageItems = items.filter(isImage) as any[];
  const playerTokens = imageItems
    .filter((item) => readCombatMetadata(item).role === "pc")
    .map((item) => tokenFromItem(item, "pc"));
  const monsterTokens = imageItems
    .filter((item) => readCombatMetadata(item).role === "monster")
    .map((item) => tokenFromItem(item, "monster"));

  return {
    grid: {
      dpi,
      scaleMultiplier: scale.parsed?.multiplier ?? 5,
      scaleUnit: scale.parsed?.unit ?? "ft",
      type,
      measurement,
    },
    playerTokens,
    monsterTokens,
    blockedZones: [],
  };
}

export async function markSelectedAsPlayers(): Promise<number> {
  const ready = await isOwlbearReady();
  if (!ready) {
    return 0;
  }
  const selection = await OBR.player.getSelection();
  if (!selection || selection.length === 0) {
    return 0;
  }
  const selectedItems = await OBR.scene.items.getItems(selection);
  await OBR.scene.items.updateItems(selectedItems, (draftItems) => {
    for (const item of draftItems as any[]) {
      item.metadata = {
        ...item.metadata,
        [METADATA_KEY]: {
          ...readCombatMetadata(item),
          role: "pc",
        },
      };
    }
  });
  return selection.length;
}

export async function spawnEncounterPlan(input: {
  plan: EncounterPlan;
  tokenArt: Record<string, TokenArtMapping>;
}): Promise<void> {
  const ready = await isOwlbearReady();
  if (!ready) {
    return;
  }

  const dpi = await OBR.scene.grid.getDpi();
  const items: any[] = [];
  for (const group of input.plan.monsters) {
    for (let i = 0; i < group.count; i += 1) {
      const art = input.tokenArt[group.monsterDefinitionId];
      const position = group.suggestedPositions[i] ?? group.suggestedPositions[0] ?? { x: 0, y: 0 };
      const image = art
        ? { width: art.width, height: art.height, url: art.url, mime: art.mime }
        : placeholderImage(group.name);
      const item = buildImage(image, {
        dpi: image.width,
        offset: { x: image.width / 2, y: image.height / 2 },
      }).build() as any;

      item.name = `${group.name} ${i + 1}`;
      item.layer = "CHARACTER";
      item.position = snapLikeOwlbear(position, dpi);
      item.locked = false;
      item.metadata = {
        ...item.metadata,
        [METADATA_KEY]: {
          role: "monster",
          monsterDefinitionId: group.monsterDefinitionId,
          combatantId: createBrowserId("cmb"),
        },
      };
      item.text = {
        ...item.text,
        type: "PLAIN",
        plainText: `${group.name} ${i + 1}`,
      };
      item.textItemType = "LABEL";
      items.push(item);
    }
  }

  if (items.length > 0) {
    await OBR.scene.items.addItems(items);
  }
}

export async function applyTurnResolution(resolution: TurnResolution): Promise<void> {
  const ready = await isOwlbearReady();
  if (!ready) {
    return;
  }

  const scene = await readSceneSnapshot();
  const movedMonster = scene.monsterTokens.find((token) => token.combatantId === resolution.combatantId);
  const movementEnd = resolution.movementApplied[resolution.movementApplied.length - 1];
  const updateIds = new Set<string>();

  if (movedMonster && movementEnd) {
    updateIds.add(movedMonster.id);
  }
  for (const update of resolution.monsterUpdates) {
    const token = scene.monsterTokens.find((candidate) => candidate.combatantId === update.combatantId);
    if (token) {
      updateIds.add(token.id);
    }
  }

  if (updateIds.size === 0) {
    return;
  }

  const items = await OBR.scene.items.getItems([...updateIds]);
  await OBR.scene.items.updateItems(items, (draftItems) => {
    for (const item of draftItems as any[]) {
      const metadata = readCombatMetadata(item);
      if (metadata.role !== "monster") {
        continue;
      }
      if (movedMonster && item.id === movedMonster.id && movementEnd) {
        item.position = movementEnd;
      }
      const state = resolution.monsterUpdates.find((update) => update.combatantId === metadata.combatantId);
      if (state) {
        item.metadata = {
          ...item.metadata,
          [METADATA_KEY]: {
            ...metadata,
            defeated: state.defeated,
          },
        };
        if (state.defeated) {
          item.text = {
            ...item.text,
            type: "PLAIN",
            plainText: `${item.name ?? "Monster"} defeated`,
          };
        }
      }
    }
  });
}

export async function pickTokenArtFromAtlas(monsterDefinitionId: string): Promise<TokenArtMapping | undefined> {
  const ready = await isOwlbearReady();
  if (!ready) {
    return undefined;
  }
  const picked = await OBR.assets.downloadImages(false, "", "CHARACTER");
  const first = picked[0] as any;
  if (!first) {
    return undefined;
  }
  return {
    monsterDefinitionId,
    url: first.image.url,
    mime: first.image.mime,
    width: first.image.width,
    height: first.image.height,
  };
}

export async function uploadTokenFiles(files: FileList | File[]): Promise<number> {
  const ready = await isOwlbearReady();
  if (!ready) {
    return 0;
  }
  const uploads = [];
  for (const file of Array.from(files)) {
    const data = await file.arrayBuffer();
    const copied = new File([data], file.name, { type: file.type });
    uploads.push(buildImageUpload(copied).name(file.name).build());
  }
  if (uploads.length > 0) {
    await OBR.assets.uploadImages(uploads, "CHARACTER");
  }
  return uploads.length;
}

function tokenFromItem(item: any, kind: "pc" | "monster") {
  const metadata = readCombatMetadata(item);
  return {
    id: item.id,
    name: item.name ?? item.text?.plainText ?? "Token",
    kind,
    position: item.position ?? { x: 0, y: 0 },
    width: item.image?.width,
    height: item.image?.height,
    monsterDefinitionId: metadata.monsterDefinitionId,
    combatantId: metadata.combatantId,
  };
}

function readCombatMetadata(item: any): CombatMetadata {
  return (item.metadata?.[METADATA_KEY] ?? {}) as CombatMetadata;
}

function placeholderImage(name: string): { width: number; height: number; url: string; mime: string } {
  const initials = name
    .split(/\s+/)
    .filter(Boolean)
    .slice(0, 2)
    .map((part) => part[0]?.toUpperCase())
    .join("");
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="512" height="512" viewBox="0 0 512 512"><rect width="512" height="512" rx="256" fill="#1f2937"/><circle cx="256" cy="256" r="226" fill="none" stroke="#f59e0b" stroke-width="28"/><text x="256" y="282" text-anchor="middle" font-family="Arial, sans-serif" font-size="120" font-weight="700" fill="#f9fafb">${escapeXml(initials || "?")}</text></svg>`;
  return {
    width: 512,
    height: 512,
    mime: "image/svg+xml",
    url: `data:image/svg+xml;charset=utf-8,${encodeURIComponent(svg)}`,
  };
}

function demoSceneSnapshot(): SceneSnapshot {
  return {
    grid: {
      dpi: 100,
      scaleMultiplier: 5,
      scaleUnit: "ft",
      type: "SQUARE",
      measurement: "CHEBYSHEV",
    },
    playerTokens: [
      { id: "demo-pc-1", name: "Player Token 1", kind: "pc", position: { x: 0, y: 0 } },
      { id: "demo-pc-2", name: "Player Token 2", kind: "pc", position: { x: 220, y: 80 } },
    ],
    monsterTokens: [],
    blockedZones: [],
  };
}

function snapLikeOwlbear(position: Vector2, dpi: number): Vector2 {
  return {
    x: Math.round(position.x / (dpi / 2)) * (dpi / 2),
    y: Math.round(position.y / (dpi / 2)) * (dpi / 2),
  };
}

function createBrowserId(prefix: string): string {
  return `${prefix}_${crypto.randomUUID()}`;
}

function escapeXml(value: string): string {
  return value.replace(/[<>&"']/g, (character) => {
    switch (character) {
      case "<":
        return "&lt;";
      case ">":
        return "&gt;";
      case "&":
        return "&amp;";
      case '"':
        return "&quot;";
      default:
        return "&apos;";
    }
  });
}

