import type {
  CombatantState,
  CompanionSettings,
  EncounterPlan,
  MonsterDefinition,
  SceneSnapshot,
  TokenArtMapping,
  TurnProposal,
  TurnResolution,
} from "../shared/types";

export const DEFAULT_COMPANION_URL = "http://localhost:8765";

export type CompanionHealth = {
  ok: boolean;
  service: string;
  lmStudioBaseUrl: string;
  campaignRuleset: string;
};

export type CompanionApi = {
  health(): Promise<CompanionHealth>;
  models(): Promise<{ models: { id: string }[] }>;
  settings(): Promise<CompanionSettings>;
  updateSettings(patch: Partial<CompanionSettings>): Promise<CompanionSettings>;
  monsters(query?: string): Promise<{ monsters: MonsterDefinition[] }>;
  importMonster(monster: unknown): Promise<{ monster: MonsterDefinition; importedCount: number }>;
  updateMonster(id: string, monster: unknown): Promise<{ monster: MonsterDefinition; importedCount: number }>;
  draftMonsterFromText(text: string): Promise<{ monster: MonsterDefinition; source: "text" }>;
  draftMonsterFromImage(imageDataUrl: string, notes?: string): Promise<{ monster: MonsterDefinition; source: "image" }>;
  generateMonster(input: {
    description: string;
    targetChallengeRating?: number;
    role?: string;
  }): Promise<{ monster: MonsterDefinition; source: "description" }>;
  planEncounter(prompt: string, scene: SceneSnapshot): Promise<{ plan: EncounterPlan }>;
  syncCombat(scene: SceneSnapshot): Promise<{ combatants: CombatantState[] }>;
  proposeTurn(scene: SceneSnapshot): Promise<{ proposal: TurnProposal; combatants: CombatantState[] }>;
  resolveTurn(scene: SceneSnapshot, proposal?: TurnProposal): Promise<{
    resolution: TurnResolution;
    combatants: CombatantState[];
  }>;
};

export function createCompanionApi(baseUrl: string): CompanionApi {
  const base = baseUrl.replace(/\/+$/, "");
  return {
    health: () => request(base, "/health"),
    models: () => request(base, "/models"),
    settings: () => request(base, "/settings"),
    updateSettings: (patch) => request(base, "/settings", { method: "PUT", body: patch }),
    monsters: (query) =>
      request(base, `/compendium/monsters${query ? `?query=${encodeURIComponent(query)}` : ""}`),
    importMonster: (monster) => request(base, "/compendium/import", { method: "POST", body: { monster } }),
    updateMonster: (id, monster) =>
      request(base, `/compendium/monsters/${encodeURIComponent(id)}`, { method: "PUT", body: { monster } }),
    draftMonsterFromText: (text) =>
      request(base, "/compendium/draft-from-text", { method: "POST", body: { text } }),
    draftMonsterFromImage: (imageDataUrl, notes) =>
      request(base, "/compendium/draft-from-image", { method: "POST", body: { imageDataUrl, notes } }),
    generateMonster: (input) =>
      request(base, "/compendium/generate", { method: "POST", body: input }),
    planEncounter: (prompt, scene) => request(base, "/encounter/plan", { method: "POST", body: { prompt, scene } }),
    syncCombat: (scene) => request(base, "/combat/sync", { method: "POST", body: { scene } }),
    proposeTurn: (scene) => request(base, "/turn/propose", { method: "POST", body: { scene } }),
    resolveTurn: (scene, proposal) => request(base, "/turn/resolve", { method: "POST", body: { scene, proposal } }),
  };
}

export async function saveTokenArt(
  api: CompanionApi,
  settings: CompanionSettings,
  art: TokenArtMapping,
): Promise<CompanionSettings> {
  return api.updateSettings({
    tokenArt: {
      ...settings.tokenArt,
      [art.monsterDefinitionId]: art,
    },
  });
}

async function request<T>(
  base: string,
  path: string,
  init: { method?: string; body?: unknown } = {},
): Promise<T> {
  const response = await fetch(`${base}${path}`, {
    method: init.method ?? "GET",
    headers: init.body === undefined ? undefined : { "Content-Type": "application/json" },
    body: init.body === undefined ? undefined : JSON.stringify(init.body),
  });
  const payload = (await response.json()) as T & { error?: string };
  if (!response.ok) {
    throw new Error(payload.error ?? `Companion request failed: ${response.status}`);
  }
  return payload;
}
